import numpy as np

# Ekstraksi Triplet Kanonikal Sederhana berbasis Heuristik Token & POS Tag
def simple_triple_extractor(tokens, entities, relation_keywords):
    # entities: list of dict {'text': str, 'type': str, 'start': int, 'end': int}
    triples = []
    for i in range(len(entities)):
        for j in range(len(entities)):
            if i == j:
                continue
            ent1, ent2 = entities[i], entities[j]
            # Cari kata kunci relasi di antara kedua entitas
            if ent1['end'] <= ent2['start']:
                span_tokens = tokens[ent1['end']:ent2['start']]
                span_text = ' '.join(span_tokens).lower()
                for rel_name, patterns in relation_keywords.items():
                    if any(p in span_text for p in patterns):
                        triples.append((ent1['text'], rel_name, ent2['text']))
    return triples

