for s, p, o in extracted_triples:
    print(f"  <Subject: '{s}'> --[Predicate: '{p}']--> <Object: '{o}'>")

import numpy as np

# Ekstraksi Argumen Peristiwa (Event Extraction) Sederhana berbasis Atribut Jarak
def extract_event_arguments(trigger_idx, trigger_type, candidate_entities, max_dist=8):
    # candidate_entities: list of dict {'text': str, 'type': str, 'idx': int}
    role_assignments = []

    for ent in candidate_entities:
        dist = abs(ent['idx'] - trigger_idx)
        if dist <= max_dist:
            role = 'Unknown'
            if trigger_type == 'Conflict:Attack':
                if ent['type'] == 'PERSON' and ent['idx'] < trigger_idx:
                    role = 'Attacker'
                elif ent['type'] == 'PERSON' and ent['idx'] > trigger_idx:
                    role = 'Target'
                elif ent['type'] == 'WEAPON':
                    role = 'Instrument'
                elif ent['type'] == 'GPE':
                    role = 'Place'
            role_assignments.append((ent['text'], role, dist))
    return role_assignments

