import numpy as np

# Validasi Konsistensi Integritas Fakta Berbasis Aturan Bentuk (SHACL Style Validation)
def validate_kg_triples(triples, constraints):
    violations = []
    # Kumpulkan properti per entitas
    entity_props = {}
    for s, p, o in triples:
        if s not in entity_props:
            entity_props[s] = {}
        if p not in entity_props[s]:
            entity_props[s][p] = []
        entity_props[s][p].append(o)

    for ent, props in entity_props.items():
        # Periksa batasan kelas Human
        if props.get('type') == ['Human']:
            # Batasan 1: Tepat 1 birth_year
            births = props.get('birth_year', [])
            if len(births) != 1:
                violations.append(f"{ent}: Pelanggaran kardinalitas birth_year (Ditemukan {len(births)}, harus tepat 1)")
            # Batasan 2: death_year >= birth_year
            deaths = props.get('death_year', [])
            if births and deaths:
                if int(deaths[0]) < int(births[0]):
                    violations.append(f"{ent}: Anomali temporal (Tahun wafat {deaths[0]} mendahului tahun lahir {births[0]})")
    return violations

